import{_ as n,I as t,o,c as l,b6 as a,j as d,J as i,w as c}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse(`{"title":"Développement pratique d'un système de recommandation de films avec Spring Boot","description":"","frontmatter":{},"headers":[],"relativePath":"fr-fr/stage-2/assignments/movie-recommendation-springboot/index.md","filePath":"fr-fr/stage-2/assignments/movie-recommendation-springboot/index.md"}`),p={name:"fr-fr/stage-2/assignments/movie-recommendation-springboot/index.md"},u={style:{margin:"32px 0"}};function m(f,e,h,b,g,v){const s=t("StepBar"),r=t("ClientOnly");return o(),l("div",null,[e[0]||(e[0]=a('<h1 id="developpement-pratique-d-un-systeme-de-recommandation-de-films-avec-spring-boot" tabindex="-1">Développement pratique d&#39;un système de recommandation de films avec Spring Boot <a class="header-anchor" href="#developpement-pratique-d-un-systeme-de-recommandation-de-films-avec-spring-boot" aria-label="Permalink to “Développement pratique d&#39;un système de recommandation de films avec Spring Boot”">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to “Aperçu”">​</a></h2><p>Ce projet pratique vous demande de réaliser, à partir d&#39;un véritable PRD, un site web de films avec capacités de recommandation en utilisant Spring Boot. Le défi principal de ce projet est qu&#39;il ne s&#39;agit pas d&#39;un simple CRUD, mais qu&#39;il vous amène à réfléchir à la manière dont les comportements des utilisateurs influencent les résultats de recommandation et à rendre ces recommandations explicables.</p><p>Il s&#39;agit du projet pratique synthétique de l&#39;Étape 2. Vous découvrirez pour la première fois le modèle de développement de produits de type « contenu + comportement + recommandation », très courant dans le e-commerce, les plateformes de contenu et les flux personnalisés.</p><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to “Prérequis”">​</a></h2><p>Avant de commencer ce projet, vous devriez maîtriser les éléments suivants :</p><ul><li>Conception de pages frontales et utilisation de bibliothèques de composants (<a href="./../../frontend/ui-design/">Conception UI</a>, <a href="./../../frontend/modern-component-library/">Bibliothèque de composants moderne</a>)</li><li>Conception et développement d&#39;API backend (<a href="./../../backend/ai-interface-code/">Écriture de code d&#39;interface</a>)</li><li>Bases de données et Supabase (<a href="./../../backend/database-supabase/">Des bases de données à Supabase</a>)</li><li>Flux de travail Git et déploiement (<a href="./../../backend/git-workflow/">Git et GitHub</a>, <a href="./../../backend/zeabur-deployment/">Déployer une application web</a>)</li></ul><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to “Objectifs d&#39;apprentissage”">​</a></h2><p>Après avoir terminé ce projet, vous serez capable de :</p><ol><li>Lire un PRD et en extraire une liste de tâches de développement pour un système de recommandation</li><li>Utiliser Spring Boot pour mettre en place un projet backend et implémenter des API RESTful</li><li>Concevoir le flux de données complet « comportement utilisateur -&gt; recommandation »</li><li>Implémenter une logique de recommandation explicable</li><li>Effectuer des tests de bout en bout et livrer un prototype de produit démontrable</li></ol><h2 id="presentation-du-projet" tabindex="-1">Présentation du projet <a class="header-anchor" href="#presentation-du-projet" aria-label="Permalink to “Présentation du projet”">​</a></h2><p>Le produit que vous allez construire est un site web de films avec capacités de recommandation :</p><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Description</th></tr></thead><tbody><tr><td><strong>Navigation et recherche</strong></td><td>Les utilisateurs peuvent parcourir et rechercher des films</td></tr><tr><td><strong>Notes et favoris</strong></td><td>Les utilisateurs peuvent noter des films et les ajouter aux favoris</td></tr><tr><td><strong>Recommandations personnalisées</strong></td><td>Le système génère des recommandations basées sur le comportement des utilisateurs</td></tr><tr><td><strong>Back-office</strong></td><td>Les administrateurs gèrent les données des films et consultent l&#39;efficacité des recommandations</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Accès au PRD</p><p>Le document d&#39;exigences de ce projet se trouve sur GitHub : <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/fr-fr/stage-2/assignments/movie-recommendation-springboot/PRD.md" target="_blank" rel="noreferrer">Voir le PRD</a></p></div>',14)),d("div",u,[i(r,null,{default:c(()=>[i(s,{active:0,items:[{title:"Analyse des besoins",description:"Lire le PRD, clarifier la stratégie de recommandation, les données comportementales et le périmètre du back-office"},{title:"Construction du squelette",description:"Générer avec l'IA le squelette des pages liste, détails, recommandations et back-office"},{title:"Développement itératif",description:"Compléter la logique de recommandation, l'enregistrement des comportements et la gestion du back-office"},{title:"Tests et mise en ligne",description:"Tests de bout en bout, déploiement et préparation de la démonstration"}]})]),_:1})]),e[1]||(e[1]=a(`<h2 id="partie-1-analyse-des-besoins" tabindex="-1">Partie 1 : Analyse des besoins <a class="header-anchor" href="#partie-1-analyse-des-besoins" aria-label="Permalink to “Partie 1 : Analyse des besoins”">​</a></h2><h3 id="_1-1-lire-le-prd" tabindex="-1">1.1 Lire le PRD <a class="header-anchor" href="#_1-1-lire-le-prd" aria-label="Permalink to “1.1 Lire le PRD”">​</a></h3><p>Ouvrez le document PRD et répondez aux questions suivantes :</p><ul><li>Quels comportements utilisateur sont suivis (notes, favoris, historique de visualisation) ?</li><li>Quelle est la stratégie de recommandation (filtrage collaboratif, basée sur le contenu, hybride) ?</li><li>Comment les recommandations sont-elles rendues explicables pour l&#39;utilisateur ?</li><li>Quelles sont les fonctionnalités du MVP ?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Si les questions ci-dessus n&#39;ont pas de réponse claire, ne commencez pas à coder. Une mauvaise compréhension des besoins est la cause la plus fréquente de retour en arrière.</p></div><h2 id="partie-2-construction-du-squelette-du-projet" tabindex="-1">Partie 2 : Construction du squelette du projet <a class="header-anchor" href="#partie-2-construction-du-squelette-du-projet" aria-label="Permalink to “Partie 2 : Construction du squelette du projet”">​</a></h2><h3 id="_2-1-generer-les-pages-frontales" tabindex="-1">2.1 Générer les pages frontales <a class="header-anchor" href="#_2-1-generer-les-pages-frontales" aria-label="Permalink to “2.1 Générer les pages frontales”">​</a></h3><p>Prompt de référence :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Veuillez générer, sur la base du PRD actuel, le squelette frontend d&#39;un site web de films avec système de recommandation.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Exigences :</span></span>
<span class="line"><span>1. Page d&#39;accueil avec films populaires et recommandations personnalisées</span></span>
<span class="line"><span>2. Page de liste de films avec recherche et filtrage</span></span>
<span class="line"><span>3. Page de détail d&#39;un film avec notes et avis</span></span>
<span class="line"><span>4. Page de profil avec favoris et historique</span></span>
<span class="line"><span>5. Back-office pour la gestion des films et le suivi des recommandations</span></span>
<span class="line"><span>6. Générer d&#39;abord uniquement la structure des pages et des données fictives</span></span></code></pre></div><h3 id="_2-2-verifier-la-structure-des-pages" tabindex="-1">2.2 Vérifier la structure des pages <a class="header-anchor" href="#_2-2-verifier-la-structure-des-pages" aria-label="Permalink to “2.2 Vérifier la structure des pages”">​</a></h3><ul><li>[ ] La page d&#39;accueil affiche-t-elle les recommandations ?</li><li>[ ] La page de détail permet-elle de noter et d&#39;ajouter aux favoris ?</li><li>[ ] Le back-office permet-il la gestion des films ?</li></ul><h2 id="partie-3-developpement-iteratif" tabindex="-1">Partie 3 : Développement itératif <a class="header-anchor" href="#partie-3-developpement-iteratif" aria-label="Permalink to “Partie 3 : Développement itératif”">​</a></h2><h3 id="_3-1-progresser-par-module" tabindex="-1">3.1 Progresser par module <a class="header-anchor" href="#_3-1-progresser-par-module" aria-label="Permalink to “3.1 Progresser par module”">​</a></h3><ol><li><strong>Gestion des films</strong> : CRUD des films, recherche et filtrage</li><li><strong>Notes et favoris</strong> : Les utilisateurs peuvent noter et sauvegarder des films</li><li><strong>Suivi des comportements</strong> : Enregistrement des notes, favoris et historique de navigation</li><li><strong>Logique de recommandation</strong> : Algorithme de recommandation basé sur les comportements</li><li><strong>Explicabilité</strong> : Afficher pourquoi un film est recommandé (ex: « Recommandé car vous avez aimé X »)</li><li><strong>Back-office</strong> : Gestion des films et suivi de l&#39;efficacité des recommandations</li></ol><h3 id="_3-2-modele-de-donnees-de-reference" tabindex="-1">3.2 Modèle de données de référence <a class="header-anchor" href="#_3-2-modele-de-donnees-de-reference" aria-label="Permalink to “3.2 Modèle de données de référence”">​</a></h3><p>Tables principales :</p><ul><li><code>movies</code> : id, title, genre, description, release_year, rating_avg</li><li><code>user_ratings</code> : id, user_id, movie_id, rating, created_at</li><li><code>user_favorites</code> : id, user_id, movie_id, created_at</li><li><code>user_views</code> : id, user_id, movie_id, viewed_at</li><li><code>recommendations</code> : id, user_id, movie_id, reason, score, created_at</li></ul><h2 id="partie-4-tests-et-mise-en-ligne" tabindex="-1">Partie 4 : Tests et mise en ligne <a class="header-anchor" href="#partie-4-tests-et-mise-en-ligne" aria-label="Permalink to “Partie 4 : Tests et mise en ligne”">​</a></h2><h3 id="_4-1-tests-de-bout-en-bout" tabindex="-1">4.1 Tests de bout en bout <a class="header-anchor" href="#_4-1-tests-de-bout-en-bout" aria-label="Permalink to “4.1 Tests de bout en bout”">​</a></h3><ul><li>Parcourir les films -&gt; Noter un film -&gt; Voir les recommandations mises à jour</li><li>Ajouter aux favoris -&gt; Vérifier que les recommandations en tiennent compte</li></ul><h3 id="_4-2-deploiement" tabindex="-1">4.2 Déploiement <a class="header-anchor" href="#_4-2-deploiement" aria-label="Permalink to “4.2 Déploiement”">​</a></h3><ul><li>Déployer le frontend sur Vercel / Zeabur</li><li>Déployer le backend Spring Boot sur Zeabur / Railway / Render</li><li>Utiliser Supabase ou PostgreSQL comme base de données</li></ul><h2 id="livrables" tabindex="-1">Livrables <a class="header-anchor" href="#livrables" aria-label="Permalink to “Livrables”">​</a></h2><ul><li>[ ] Un lien de démonstration en ligne accessible</li><li>[ ] Un lien vers le dépôt de code source (avec README)</li><li>[ ] Le document PRD</li><li>[ ] Des captures d&#39;écran des pages principales</li><li>[ ] Une vidéo de démonstration de 60 secondes</li></ul><h2 id="criteres-d-evaluation" tabindex="-1">Critères d&#39;évaluation <a class="header-anchor" href="#criteres-d-evaluation" aria-label="Permalink to “Critères d&#39;évaluation”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Exigences de base</th><th>Exigences avancées</th></tr></thead><tbody><tr><td>Films</td><td>Navigation, recherche, détails fonctionnent</td><td>Les notes et favoris sont sauvegardés</td></tr><tr><td>Recommandation</td><td>Des recommandations sont affichées</td><td>Elles sont basées sur le comportement et sont explicables</td></tr><tr><td>Technique</td><td>Spring Boot fonctionne avec la base de données</td><td>Gestion des erreurs et optimisation des performances</td></tr><tr><td>Livraison</td><td>Le projet peut être exécuté et déployé</td><td>README clair et vidéo de démonstration</td></tr></tbody></table><h2 id="references" tabindex="-1">Références <a class="header-anchor" href="#references" aria-label="Permalink to “Références”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Conception UI</a></li><li><a href="./../../frontend/modern-component-library/">Bibliothèque de composants moderne</a></li><li><a href="./../../backend/database-supabase/">Des bases de données à Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Écriture de code d&#39;interface assistée par IA</a></li><li><a href="./../../backend/git-workflow/">Flux de travail Git et GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Comment déployer une application web</a></li></ul>`,28))])}const k=n(p,[["render",m]]);export{P as __pageData,k as default};
